import{_ as o,l as i,o as e,c as s,v as r,p as n,x as t,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"蜂窝：RAN 与核心网","description":"","frontmatter":{"title":"蜂窝：RAN 与核心网","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/cellular-ran-core.md","filePath":"cs/cellular-ran-core.md","lastUpdated":1789023840000}'),A={name:"cs/cellular-ran-core.md"};function h(E,a,P,_,u,N){const l=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=r('<h1 id="蜂窝-ran-与核心网" tabindex="-1">蜂窝：RAN 与核心网 <a class="header-anchor" href="#蜂窝-ran-与核心网" aria-label="Permalink to &quot;蜂窝：RAN 与核心网&quot;">​</a></h1><div class="epigraph"><p>空口在基站结束；用户的会话、鉴权与路由在核心网。RAN 与核心的接口让无线跳可以换代而不改「号码与数据」的合同。</p><footer>—— 据 3GPP TS 23.501（5G 架构）与 LTE EPC 对照；Kurose and Ross 蜂窝节整理</footer></div><p><a href="/cs/bluetooth-ble">上一课</a> 是无牌照短距。手机要移动、要计费、要跨城。缺口是<strong>蜂窝两段</strong>：RAN（UE–gNB/eNB）与核心（EPC 或 5GC）。本课不把网络切片 SLA 写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Wi‑Fi 的「核心」往往是一台路由器加 DHCP。蜂窝：空口调度、切换、无线承载在 RAN；附着、会话、策略、对互联网的 PDU 会话在核心。用户 IP 通常在核心锚点分配，基站像一跳隧道端——对照后课 GRE/GTP。移动性：换基站不换 IP 锚，才像「一直在线」。这不是 MAC 学习能做的：地址在三层锚，不是二层泛洪。</p><p><span class="marginnote">LTE：eNB + EPC（MME/SGW/PGW）。5G：gNB + AMF/SMF/UPF。本课钉分工，不背网元缩写表。</span></p><h3 id="基站不是交换机" tabindex="-1">基站不是交换机 <a class="header-anchor" href="#基站不是交换机" aria-label="Permalink to &quot;基站不是交换机&quot;">​</a></h3><p>用户 IP 在核心锚，换 gNB 不换锚。空口 \\(C\\) 与核心转发是两段预算。鉴权在核心，RAN 只消耗密钥。不要把 5G 写成更快 Wi‑Fi。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画：UE ↔ RAN ↔ 核心 ↔ 互联网。对照 802.11：AP 桥到同一广播域；gNB 不把以太网洪泛到全国。鉴权在核心，空口只消耗密钥。容量：小区 \\(B\\) 与干扰决定空口 \\(C\\)，核心是交换与策略。</p>',10)),(e(),n(c,null,{default:t(()=>[p(l,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20UE%5B%22%E7%BB%88%E7%AB%AF%22%5D%20--%3E%20RAN%5B%22RAN%20%E8%B0%83%E5%BA%A6%E4%B8%8E%E6%97%A0%E7%BA%BF%22%5D%0A%20%20RAN%20--%3E%20CORE%5B%22%E6%A0%B8%E5%BF%83%3A%20%E4%BC%9A%E8%AF%9D%E4%B8%8E%E9%94%9A%E7%82%B9%22%5D%0A%20%20CORE%20--%3E%20INET%5B%22%E4%BA%92%E8%81%94%E7%BD%91%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>方法止于选定对象与对照；机制才说它如何嵌入已有分层与主干课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>自协商变成能力与频段登记。PFC 无对应物；无线用调度与 QoS 承载。TCP 看到的 RTT 含空口调度时延，后课无线 TCP 会收回。主干 NAT 课：运营商常在锚点后做 NAT，与家庭路由同类但规模不同。</p><p>切换：RAN 先保住无线，核心更新转发；失败才掉 PDU 会话。GTP 隧道把基站接到锚点，中间仍是 IP 转发，不是 MAC 学习。</p><p>计费与政策在核心执行，空口只执行已授权的 QoS 规则。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 IMS 语音全程。5G 切片与 URLLC 是下一课。后课默认：蜂窝 = RAN + 核心锚点；基站不是以太网交换机。</p><p>不要把「5G 等于更快 Wi‑Fi」当架构结论。</p><p>上一课留下的缺口在本课收口；「蜂窝：RAN 与核心网」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。下一课<a href="/cs/5g-slicing">5G 切片与 URLLC</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>RAN 管空口；核心管会话、移动性锚与出网。</li><li>用户 IP 在锚点，不靠二层洪泛跨城。</li><li>空口 \\(C\\) 与核心转发是两段预算。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：3GPP TS 23.501；Kurose and Ross。</li></ul>',11))])}const R=o(A,[["render",h]]);export{T as __pageData,R as default};
